input.content:
@font-face {
  font-family: 'Archivo Black';
  src: url('./fonts/archivo-black.woff2') format('woff2');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Space Grotesk';
  src: url('./fonts/space-grotesk.woff2') format('woff2');
  font-weight: 300 700;
  font-display: swap;
}

:root {
  --bg: #070a13;
  --panel: rgba(10, 14, 26, 0.72);
  --panel-2: rgba(16, 21, 38, 0.88);
  --line: rgba(255, 255, 255, 0.11);
  --line-strong: rgba(255, 255, 255, 0.2);
  --teal: #6ff2d0;
  --pink: #ff6b9d;
  --amber: #ffd166;
  --violet: #9b8bff;
  --red: #ff5a4d;
  --ink: #f5f7ff;
  --muted: #9aa3bd;
  --display: 'Archivo Black', 'Arial Black', Impact, sans-serif;
  --body: 'Space Grotesk', system-ui, -apple-system, sans-serif;
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--body);
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

button {
  font-family: inherit;
  color: inherit;
  cursor: pointer;
  border: 0;
  background: none;
}
button:focus-visible { outline: 2px solid var(--teal); outline-offset: 3px; }

#app { position: fixed; inset: 0; overflow: hidden; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }

#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 45%, rgba(2, 4, 10, 0.42) 100%),
    linear-gradient(180deg, rgba(4, 6, 14, 0.35) 0%, transparent 22%, transparent 78%, rgba(4, 6, 14, 0.5) 100%);
}

#speedlines {
  position: absolute; inset: 0; pointer-events: none; z-index: 3; opacity: 0;
  transition: opacity 0.35s ease;
  background-image: repeating-conic-gradient(from 0deg at 50% 62%, rgba(255,255,255,0.06) 0deg 0.2deg, transparent 0.2deg 5deg);
  mask-image: radial-gradient(circle at 50% 60%, transparent 0%, black 65%);
  -webkit-mask-image: radial-gradient(circle at 50% 60%, transparent 0%, black 65%);
  animation: speedSpin 8s linear infinite;
}
#speedlines.fast { opacity: 0.5; }
@keyframes speedSpin { to { transform: rotate(6deg) scale(1.06); } }

.hidden { display: none !important; }

/* ============================ HUD ============================ */
#hud {
  position: absolute; inset: 0; z-index: 5; pointer-events: none;
  padding: calc(18px + var(--safe-t)) calc(22px + var(--safe-r)) calc(18px + var(--safe-b)) calc(22px + var(--safe-l));
}
#hud button, #hud .joystick { pointer-events: auto; }

.hud-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; }

.brand { display: flex; align-items: center; gap: 12px; filter: drop-shadow(0 2px 12px rgba(0,0,0,.5)); }
.brand-mark {
  width: 48px; height: 48px; display: grid; place-items: center;
  font-family: var(--display); font-size: 27px; color: #071016;
  background: linear-gradient(140deg, var(--teal), #3bd1ff 55%, var(--violet));
  border-radius: 12px; transform: skew(-7deg);
  box-shadow: 0 0 24px rgba(111, 242, 208, 0.45), inset 0 0 0 1px rgba(255,255,255,.45);
}
.brand-text { display: flex; flex-direction: column; line-height: 1; }
.brand-text strong { font-family: var(--display); font-size: 22px; letter-spacing: 0.7px; }
.brand-text span { font-size: 9.5px; letter-spacing: 3.2px; color: var(--teal); margin-top: 4px; }

.stat-pills { display: flex; gap: 10px; margin-top: 2px; }
.pill {
  min-width: 116px; padding: 9px 14px 8px; border-radius: 10px;
  background: var(--panel); border: 1px solid var(--line);
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 8px 26px rgba(0,0,0,.25), inset 0 1px 0 rgba(255,255,255,.07);
  display: flex; flex-direction: column; gap: 1px;
}
.pill-label { font-size: 8.5px; letter-spacing: 2.4px; color: var(--muted); }
.pill-value { font-family: var(--display); font-size: 21px; letter-spacing: 0.5px; }
.money-pill .pill-value { color: var(--amber); text-shadow: 0 0 18px rgba(255, 209, 102, .35); }
.score-pill .pill-value { color: var(--teal); }

.hud-right { display: flex; flex-direction: column; align-items: flex-end; gap: 10px; }
.hud-buttons { display: flex; gap: 8px; }
.icon-btn {
  height: 36px; min-width: 38px; padding: 0 12px; border-radius: 9px;
  background: var(--panel); border: 1px solid var(--line); backdrop-filter: blur(12px);
  font-size: 12px; font-weight: 700; letter-spacing: 1.2px; color: var(--ink);
  transition: border-color .18s, background .18s, transform .18s;
}
.icon-btn:hover { border-color: var(--teal); background: rgba(111,242,208,.12); transform: translateY(-1px); }
.shop-icon { border-color: rgba(255, 209, 102, .45); color: var(--amber); }

.minimap-wrap {
  position: relative; width: 168px; height: 168px; border-radius: 50%;
  padding: 7px; background: var(--panel); border: 1px solid var(--line);
  box-shadow: 0 10px 30px rgba(0,0,0,.35), inset 0 0 0 1px rgba(255,255,255,.04);
  backdrop-filter: blur(10px);
}
#minimap { width: 100%; height: 100%; border-radius: 50%; display: block; }
.minimap-label {
  position: absolute; bottom: -3px; left: 50%; transform: translateX(-50%);
  font-size: 8px; letter-spacing: 2.4px; color: var(--muted);
  background: #0b0f1b; border: 1px solid var(--line); padding: 3px 9px; border-radius: 20px;
  white-space: nowrap;
}

/* quests */
.quests {
  position: absolute; top: calc(98px + var(--safe-t)); left: calc(26px + var(--safe-l));
  width: 276px; pointer-events: auto;
}
.quests-head {
  display: flex; justify-content: space-between; align-items: center;
  font-size: 9px; letter-spacing: 2.4px; color: var(--muted); padding: 0 3px 7px;
}
.mini-btn {
  width: 24px; height: 24px; border-radius: 6px; border: 1px solid var(--line);
  background: rgba(255,255,255,.04); font-size: 14px; line-height: 1; color: var(--muted);
  transition: .18s;
}
.mini-btn:hover { color: var(--teal); border-color: var(--teal); }
#questList { display: flex; flex-direction: column; gap: 7px; }
.quest-card {
  display: flex; gap: 10px; align-items: center; padding: 9px 11px;
  background: var(--panel); border: 1px solid var(--line); border-radius: 10px;
  backdrop-filter: blur(12px); box-shadow: 0 6px 18px rgba(0,0,0,.22);
  position: relative; overflow: hidden; transition: border-color .25s, transform .25s;
}
.quest-card.done { border-color: rgba(111,242,208,.6); }
.quest-icon {
  width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center;
  font-size: 15px; flex: 0 0 auto; background: rgba(255,255,255,.06); border: 1px solid var(--line);
}
.quest-body { flex: 1; min-width: 0; }
.quest-title { font-size: 11.5px; font-weight: 700; letter-spacing: .2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.quest-desc { font-size: 10px; color: var(--muted); margin-top: 1px; }
.quest-reward { font-size: 10px; font-weight: 700; color: var(--amber); margin-top: 3px; letter-spacing: .4px; }
.quest-progress { height: 3px; background: rgba(255,255,255,.09); border-radius: 4px; margin-top: 5px; overflow: hidden; }
.quest-progress i { display: block; height: 100%; width: 0%; border-radius: 4px; background: linear-gradient(90deg, var(--teal), #4ecbff); transition: width .35s ease; }
.quest-reroll {
  position: absolute; right: 5px; top: 5px; width: 18px; height: 18px; border-radius: 5px;
  font-size: 11px; color: var(--muted); opacity: 0; transition: .2s; background: rgba(0,0,0,.4);
}
.quest-card:hover .quest-reroll { opacity: 1; }
.quest-reroll:hover { color: var(--teal); }

/* location banner */
.location-banner {
  position: absolute; top: calc(22% + var(--safe-t)); left: 50%; transform: translateX(-50%);
  text-align: center; pointer-events: none; text-shadow: 0 4px 24px rgba(0,0,0,.65);
  animation: bannerIn 4.4s ease forwards;
}
.loc-kicker { display: block; font-size: 9px; letter-spacing: 4px; color: var(--teal); margin-bottom: 4px; }
.location-banner strong { font-family: var(--display); font-size: clamp(20px, 3vw, 36px); letter-spacing: 1px; }
@keyframes bannerIn {
  0% { opacity: 0; transform: translate(-50%, 12px); }
  12% { opacity: 1; transform: translate(-50%, 0); }
  76% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -8px); }
}

/* combo / trick pop */
.combo-box {
  position: absolute; top: calc(78px + var(--safe-t)); left: 50%; transform: translateX(-50%);
  display: flex; align-items: baseline; gap: 12px; padding: 8px 18px;
  background: rgba(8, 11, 20, .68); border: 1px solid rgba(111,242,208,.35); border-radius: 9px;
  backdrop-filter: blur(10px); box-shadow: 0 0 26px rgba(111,242,208,.16);
  font-size: 12px; letter-spacing: 2px; color: var(--teal);
}
.combo-box strong { font-family: var(--display); font-size: 22px; color: var(--ink); letter-spacing: 0; }
.combo-box.hot { border-color: var(--pink); color: var(--pink); box-shadow: 0 0 30px rgba(255,107,157,.3); }

.trick-pop {
  position: absolute; top: 38%; left: 50%; transform: translate(-50%, -50%);
  text-align: center; pointer-events: none; z-index: 8;
  animation: trickPop 1.7s cubic-bezier(.2,1.3,.4,1) forwards;
}
.trick-pop span {
  display: block; font-family: var(--display); font-size: clamp(34px, 6vw, 72px);
  letter-spacing: 1px; color: var(--trick-color, var(--amber));
  text-shadow: 0 0 34px color-mix(in srgb, var(--trick-color, var(--amber)) 60%, transparent), 0 6px 0 rgba(0,0,0,.35);
  -webkit-text-stroke: 1px rgba(255,255,255,.25);
}
.trick-pop em { font-style: normal; display: inline-block; margin-top: 2px; font-family: var(--display); font-size: 22px; color: var(--ink); letter-spacing: 2px; }
@keyframes trickPop {
  0% { opacity: 0; transform: translate(-50%, -46%) scale(.7); }
  18% { opacity: 1; transform: translate(-50%, -50%) scale(1.06); }
  30% { transform: translate(-50%, -50%) scale(1); }
  78% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -58%) scale(.98); }
}

/* toasts */
.toasts { position: absolute; left: 50%; bottom: calc(150px + var(--safe-b)); transform: translateX(-50%); display: flex; flex-direction: column; gap: 7px; align-items: center; pointer-events: none; }
.toast {
  padding: 8px 16px; border-radius: 8px; background: rgba(8, 11, 20, .82);
  border: 1px solid var(--line-strong); font-size: 11.5px; letter-spacing: .5px;
  backdrop-filter: blur(10px); animation: toastIn .35s ease, toastOut .4s ease 2.9s forwards;
  box-shadow: 0 8px 26px rgba(0,0,0,.4); max-width: 420px; text-align: center;
}
.toast.gold { border-color: rgba(255,209,102,.55); color: var(--amber); }
.toast.teal { border-color: rgba(111,242,208,.5); color: var(--teal); }
.toast.red { border-color: rgba(255,90,77,.55); color: #ff9389; }
@keyframes toastIn { from { opacity: 0; transform: translateY(10px) scale(.96); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px); } }

/* speedo */
.speedo {
  position: absolute; left: calc(24px + var(--safe-l)); bottom: calc(22px + var(--safe-b));
  width: 164px; height: 164px; pointer-events: none;
  filter: drop-shadow(0 8px 22px rgba(0,0,0,.45));
}
.speedo-svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
.speedo-track { fill: rgba(8, 11, 20, .5); stroke: rgba(255,255,255,.1); stroke-width: 9; }
.speedo-fill {
  fill: none; stroke: url(#speedGrad); stroke-width: 9; stroke-linecap: round;
  stroke-dasharray: 440; stroke-dashoffset: 440;
  transition: stroke-dashoffset .12s linear;
  filter: drop-shadow(0 0 6px rgba(111,242,208,.55));
}
.speedo-center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.speedo-center strong { font-family: var(--display); font-size: 40px; line-height: .9; letter-spacing: -1px; }
.speedo-center span { font-size: 8px; letter-spacing: 3px; color: var(--muted); margin-top: 5px; }
.speedo-scooter { position: absolute; bottom: -4px; left: 50%; transform: translateX(-50%); white-space: nowrap; font-size: 8px; letter-spacing: 2px; color: var(--teal); background: #0a0e1a; padding: 3px 8px; border-radius: 10px; border: 1px solid var(--line); }

/* meters */
.move-meters {
  position: absolute; left: 50%; bottom: calc(26px + var(--safe-b)); transform: translateX(-50%);
  width: min(330px, 40vw); display: flex; flex-direction: column; align-items: center; gap: 8px;
}
.meter { width: 100%; padding: 9px 12px 11px; background: var(--panel); border: 1px solid var(--line); border-radius: 10px; backdrop-filter: blur(12px); box-shadow: 0 8px 24px rgba(0,0,0,.3); }
.meter-head { display: flex; justify-content: space-between; font-size: 8px; letter-spacing: 2px; color: var(--muted); margin-bottom: 6px; }
.meter-head span:first-child { color: var(--teal); }
.meter-track { position: relative; height: 8px; border-radius: 6px; background: rgba(255,255,255,.09); overflow: hidden; }
.meter-green { position: absolute; left: 32%; width: 45%; top: 0; bottom: 0; background: linear-gradient(90deg, rgba(111,242,208,.25), rgba(111,242,208,.7), rgba(111,242,208,.25)); }
.meter-marker { position: absolute; top: -3px; width: 4px; height: 14px; margin-left: -2px; background: #fff; border-radius: 3px; box-shadow: 0 0 10px #fff; transition: left .06s linear; }
.meter.danger .meter-marker { background: var(--red); box-shadow: 0 0 10px var(--red); }

.rot-dial { display: flex; align-items: center; gap: 10px; padding: 8px 14px 8px 8px; background: var(--panel); border: 1px solid var(--line); border-radius: 10px; backdrop-filter: blur(12px); box-shadow: 0 8px 24px rgba(0,0,0,.3); }
.rot-ring {
  position: relative; width: 66px; height: 66px; border-radius: 50%;
  background: conic-gradient(from -68deg, rgba(111,242,208,.6) 0deg 136deg, rgba(255,255,255,.07) 136deg 360deg);
  mask: radial-gradient(circle, transparent 52%, #000 54%);
  -webkit-mask: radial-gradient(circle, transparent 52%, #000 54%);
}
.rot-needle { position: absolute; left: 50%; top: 4px; width: 3px; height: 26px; margin-left: -1.5px; background: #fff; border-radius: 2px; transform-origin: 50% 29px; box-shadow: 0 0 8px #fff; }
.rot-hub { position: absolute; left: 50%; top: 50%; width: 7px; height: 7px; margin: -3.5px 0 0 -3.5px; border-radius: 50%; background: var(--teal); }
.rot-meta { display: flex; flex-direction: column; line-height: 1.1; }
.rot-meta strong { font-size: 10px; letter-spacing: 1.4px; color: var(--teal); }
.rot-meta span { font-family: var(--display); font-size: 17px; margin-top: 3px; }

/* trick buttons */
.trick-buttons {
  position: absolute; right: calc(24px + var(--safe-r)); bottom: calc(24px + var(--safe-b));
  display: grid; grid-template-columns: repeat(2, minmax(96px, 120px)); gap: 8px; pointer-events: auto;
}
.trick-btn {
  height: 50px; display: flex; align-items: center; gap: 8px; padding: 0 11px;
  border-radius: 9px; background: var(--panel); border: 1px solid var(--line);
  backdrop-filter: blur(12px); opacity: .46; transition: .18s; position: relative; overflow: hidden;
}
.trick-btn::after { content: ''; position: absolute; inset: 0; background: linear-gradient(120deg, transparent, rgba(255,255,255,.08)); opacity: 0; transition: .2s; }
.trick-btn.armed { opacity: 1; border-color: color-mix(in srgb, var(--tc) 55%, transparent); box-shadow: 0 0 18px color-mix(in srgb, var(--tc) 15%, transparent); }
.trick-btn.armed::after { opacity: 1; }
.trick-btn:active { transform: scale(.97); }
.trick-btn .tb-key {
  width: 24px; height: 24px; display: grid; place-items: center; flex: 0 0 auto;
  border-radius: 5px; font-size: 11px; font-weight: 700; color: #06090f;
  background: var(--tc, var(--teal)); box-shadow: 0 0 10px color-mix(in srgb, var(--tc, var(--teal)) 45%, transparent);
}
.trick-btn .tb-name { font-size: 9px; letter-spacing: 1.1px; color: var(--ink); white-space: nowrap; }
.backflip { --tc: #ffd166; }
.frontflip { --tc: #6ff2d0; }
.sideflip { --tc: #ff6b9d; }
.barspin { --tc: #9b8bff; }

/* touch controls */
.touch-controls { display: none; }
.joystick {
  position: absolute; left: calc(20px + var(--safe-l)); bottom: calc(22px + var(--safe-b));
  width: 128px; height: 128px; border-radius: 50%; touch-action: none;
  background: radial-gradient(circle, rgba(255,255,255,.05), rgba(8,11,20,.55));
  border: 1px solid rgba(255,255,255,.16); backdrop-filter: blur(8px);
  display: grid; place-items: center;
}
.joystick-ring { position: absolute; inset: 16px; border-radius: 50%; border: 1px dashed rgba(255,255,255,.18); }
.joystick-knob {
  width: 52px; height: 52px; border-radius: 50%; background: linear-gradient(140deg, rgba(111,242,208,.9), rgba(59,209,255,.6));
  box-shadow: 0 0 22px rgba(111,242,208,.4), inset 0 0 0 1px rgba(255,255,255,.5);
  transform: translate(0, 0); transition: transform .05s linear;
}
.joy-label { position: absolute; bottom: -16px; font-size: 7px; letter-spacing: 2px; color: var(--muted); }
.touch-actions { position: absolute; right: calc(22px + var(--safe-r)); bottom: calc(150px + var(--safe-b)); display: flex; flex-direction: column; gap: 9px; align-items: flex-end; }
.touch-btn {
  border-radius: 50%; width: 72px; height: 72px; font-size: 9px; font-weight: 700; letter-spacing: 1.4px;
  background: rgba(10,14,26,.7); border: 1px solid rgba(255,255,255,.2); backdrop-filter: blur(8px);
}
.jump-btn { border-color: rgba(111,242,208,.55); color: var(--teal); box-shadow: 0 0 18px rgba(111,242,208,.12); }
.wheelie-btn { width: 60px; height: 60px; font-size: 8px; border-color: rgba(255,209,102,.45); color: var(--amber); }
.touch-btn:active { transform: scale(.95); background: rgba(111,242,208,.15); }

.controls-hint {
  position: absolute; bottom: calc(14px + var(--safe-b)); left: 50%; transform: translateX(-50%);
  display: flex; gap: 14px; padding: 6px 14px; border-radius: 8px;
  background: rgba(8,11,20,.4); border: 1px solid rgba(255,255,255,.07);
  font-size: 9px; color: var(--muted); white-space: nowrap;
  animation: hintFade 1s ease 14s forwards;
}
.controls-hint b { color: var(--ink); font-weight: 700; margin-right: 4px; }
@keyframes hintFade { to { opacity: 0; visibility: hidden; } }

.bail-box {
  position: absolute; top: 42%; left: 50%; transform: translate(-50%, -50%);
  text-align: center; padding: 18px 34px; background: rgba(20, 6, 8, .7);
  border: 1px solid rgba(255,90,77,.5); border-radius: 12px; backdrop-filter: blur(10px);
  box-shadow: 0 0 50px rgba(255,60,40,.25); animation: bailShake .4s ease;
}
.bail-box strong { display: block; font-family: var(--display); font-size: 42px; color: #ff6a5c; letter-spacing: 2px; text-shadow: 0 0 30px rgba(255,80,60,.5); }
.bail-box span { display: block; margin-top: 4px; font-size: 11px; color: #ffc0ba; letter-spacing: .5px; }
@keyframes bailShake { 0%,100% { transform: translate(-50%,-50%); } 25% { transform: translate(calc(-50% - 7px),-50%) rotate(-1deg); } 75% { transform: translate(calc(-50% + 7px),-50%) rotate(1deg); } }

/* ============================ TITLE ============================ */
.title-screen {
  position: absolute; inset: 0; z-index: 20; overflow: hidden;
  display: flex; align-items: center;
  background:
    radial-gradient(ellipse at 72% 42%, transparent 0%, rgba(6, 9, 18, 0.25) 55%, rgba(6, 9, 18, 0.82) 100%),
    linear-gradient(90deg, rgba(5, 8, 16, .96) 0%, rgba(5, 8, 16, .82) 34%, rgba(5, 8, 16, .22) 66%, rgba(5, 8, 16, 0) 100%);
}
.title-bg {
  position: absolute; inset: 0; pointer-events: none;
  background-image:
    linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.035) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: linear-gradient(90deg, black, transparent 70%);
  -webkit-mask-image: linear-gradient(90deg, black, transparent 70%);
}
.title-content { position: relative; z-index: 2; width: min(590px, 52vw); margin-left: clamp(28px, 6vw, 96px); padding: 40px 0; }
.eyebrow { display: flex; align-items: center; gap: 8px; font-size: 10px; letter-spacing: 4px; color: var(--teal); margin-bottom: 14px; }
.dot { width: 6px; height: 6px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 12px var(--teal); animation: pulse 2s infinite; }
@keyframes pulse { 50% { opacity: .35; } }
.title-logo { margin: 0; font-family: var(--display); line-height: .78; letter-spacing: -2px; }
.title-logo .volt {
  display: block; font-size: clamp(70px, 10vw, 138px);
  background: linear-gradient(175deg, #fff5cf 8%, #ffd166 38%, #ff9f1c 62%, #c86412 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 8px 0 rgba(60, 24, 6, .5)) drop-shadow(0 0 38px rgba(255, 176, 60, .22));
  transform: skew(-4deg);
}
.title-logo .city {
  display: block; font-size: clamp(70px, 10vw, 138px); color: transparent;
  -webkit-text-stroke: 2px var(--teal);
  text-shadow: 0 0 38px rgba(111, 242, 208, .28);
  transform: skew(-4deg) translateX(18px);
  letter-spacing: 1px;
}
.title-sub { margin: 18px 0 0; font-size: 12px; letter-spacing: 7px; color: var(--ink); opacity: .9; }
.title-copy { max-width: 470px; margin: 14px 0 0; font-size: 13px; line-height: 1.65; color: #b9c2d8; }
.title-actions { display: flex; gap: 12px; margin-top: 26px; align-items: center; }
.play-btn {
  position: relative; display: inline-flex; align-items: center; gap: 10px;
  padding: 15px 38px; border-radius: 11px; font-family: var(--display); font-size: 19px; letter-spacing: 2px;
  color: #061016; background: linear-gradient(120deg, var(--teal), #4ee0ff 55%, #8fd0ff);
  box-shadow: 0 0 0 1px rgba(255,255,255,.35) inset, 0 12px 34px rgba(46, 214, 196, .3), 0 0 60px rgba(111,242,208,.14);
  transition: transform .18s, box-shadow .18s;
}
.play-btn:hover { transform: translateY(-2px) scale(1.02); box-shadow: 0 0 0 1px rgba(255,255,255,.5) inset, 0 16px 40px rgba(46, 214, 196, .45), 0 0 80px rgba(111,242,208,.28); }
.play-btn:active { transform: translateY(0) scale(.99); }
.play-btn.small { padding: 12px 28px; font-size: 15px; }
.play-icon { font-size: 13px; }
.ghost-btn {
  padding: 14px 22px; border-radius: 11px; border: 1px solid rgba(255,255,255,.2);
  background: rgba(255,255,255,.045); font-size: 11px; font-weight: 700; letter-spacing: 1.8px;
  color: var(--ink); transition: .18s; backdrop-filter: blur(8px);
}
.ghost-btn:hover { border-color: var(--teal); background: rgba(111,242,208,.1); transform: translateY(-1px); }
.title-stats { display: flex; gap: 28px; margin-top: 30px; padding-top: 18px; border-top: 1px solid rgba(255,255,255,.12); width: fit-content; }
.title-stats div { display: flex; flex-direction: column; gap: 4px; }
.title-stats span { font-size: 8px; letter-spacing: 2.2px; color: var(--muted); }
.title-stats strong { font-family: var(--display); font-size: 17px; color: var(--amber); }
.title-stats div:nth-child(2) strong { color: var(--teal); }
.title-stats div:nth-child(3) strong { color: var(--pink); }
.title-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 22px; margin-top: 24px; max-width: 460px; }
.title-controls div { display: flex; align-items: baseline; gap: 8px; font-size: 10px; }
.title-controls b { font-size: 9px; letter-spacing: .8px; color: var(--teal); border: 1px solid rgba(111,242,208,.25); padding: 2px 6px; border-radius: 4px; white-space: nowrap; }
.title-controls span { color: var(--muted); }
.title-corner { position: absolute; right: 30px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; align-items: flex-end; gap: 16px; z-index: 2; }
.title-corner span { font-size: 8px; letter-spacing: 4px; color: rgba(255,255,255,.38); writing-mode: vertical-rl; }
.title-scroll { position: absolute; bottom: 24px; right: 34px; font-size: 8px; letter-spacing: 3px; color: rgba(255,255,255,.4); z-index: 2; }

/* ============================ OVERLAYS ============================ */
.overlay {
  position: absolute; inset: 0; z-index: 30; display: flex; align-items: center; justify-content: center;
  padding: 20px; background: rgba(3, 5, 11, .72); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  animation: fadeIn .22s ease;
}
@keyframes fadeIn { from { opacity: 0; } }
.panel {
  width: min(1120px, 96vw); max-height: 92vh; overflow: auto; padding: clamp(20px, 3vw, 34px);
  background: linear-gradient(160deg, rgba(18, 24, 43, .96), rgba(8, 11, 21, .98));
  border: 1px solid rgba(255,255,255,.12); border-radius: 18px;
  box-shadow: 0 40px 100px rgba(0,0,0,.65), inset 0 1px 0 rgba(255,255,255,.08);
  scrollbar-width: thin;
}
.panel::-webkit-scrollbar { width: 8px; }
.panel::-webkit-scrollbar-thumb { background: rgba(255,255,255,.15); border-radius: 8px; }
.panel-head { display: flex; align-items: flex-start; gap: 20px; flex-wrap: wrap; }
.panel-kicker { font-size: 9px; letter-spacing: 3.4px; color: var(--teal); }
.panel h2 { margin: 6px 0 0; font-family: var(--display); font-size: clamp(28px, 4vw, 46px); letter-spacing: .5px; }
.panel-copy { margin: 10px 0 20px; font-size: 12.5px; color: var(--muted); }
.shop-wallet { margin-left: auto; text-align: right; padding: 8px 14px; background: rgba(255,209,102,.07); border: 1px solid rgba(255,209,102,.25); border-radius: 10px; }
.shop-wallet span { display: block; font-size: 8px; letter-spacing: 2.4px; color: var(--muted); }
.shop-wallet strong { display: block; font-family: var(--display); font-size: 24px; color: var(--amber); margin-top: 2px; }
.close-btn {
  width: 38px; height: 38px; border-radius: 9px; border: 1px solid var(--line);
  background: rgba(255,255,255,.04); font-size: 15px; color: var(--muted); transition: .18s;
}
.close-btn:hover { color: var(--ink); border-color: var(--pink); background: rgba(255,107,157,.1); }
.shop-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.shop-card {
  position: relative; padding: 16px; border-radius: 13px; border: 1px solid var(--line);
  background: linear-gradient(160deg, rgba(255,255,255,.045), rgba(255,255,255,.012));
  transition: .22s; overflow: hidden;
}
.shop-card:hover { border-color: rgba(255,255,255,.25); transform: translateY(-2px); }
.shop-card.owned { border-color: rgba(111,242,208,.22); }
.shop-card.equipped { border-color: var(--teal); box-shadow: 0 0 30px rgba(111,242,208,.14), inset 0 0 0 1px rgba(111,242,208,.18); }
.shop-card.locked { opacity: .9; }
.sc-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
.sc-name { font-family: var(--display); font-size: 15px; letter-spacing: .3px; }
.sc-tag { font-size: 10px; color: var(--muted); line-height: 1.45; margin-top: 5px; min-height: 29px; }
.sc-badge { font-size: 8px; letter-spacing: 1.4px; padding: 4px 7px; border-radius: 4px; border: 1px solid var(--line); white-space: nowrap; }
.sc-badge.owned { color: var(--teal); border-color: rgba(111,242,208,.4); }
.sc-badge.equipped { color: #071016; background: var(--teal); border-color: var(--teal); }
.sc-art { height: 82px; margin: 10px 0 4px; position: relative; display: grid; place-items: center; }
.sc-art svg { width: 100%; height: 100%; filter: drop-shadow(0 8px 12px rgba(0,0,0,.45)); }
.sc-stats { display: flex; flex-direction: column; gap: 5px; margin: 8px 0 12px; }
.sc-stat { display: grid; grid-template-columns: 44px 1fr 34px; align-items: center; gap: 7px; font-size: 8px; letter-spacing: 1px; color: var(--muted); }
.sc-bar { height: 4px; border-radius: 4px; background: rgba(255,255,255,.09); overflow: hidden; }
.sc-bar i { display: block; height: 100%; border-radius: 4px; background: linear-gradient(90deg, var(--teal), #4ee0ff); }
.sc-stat b { font-size: 9px; color: var(--ink); text-align: right; }
.sc-foot { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding-top: 10px; border-top: 1px solid rgba(255,255,255,.08); }
.sc-price { font-family: var(--display); font-size: 17px; color: var(--amber); }
.sc-price.owned { color: var(--muted); font-size: 12px; letter-spacing: 1px; }
.buy-btn { padding: 9px 15px; border-radius: 7px; font-size: 10px; font-weight: 700; letter-spacing: 1.4px; background: var(--amber); color: #171004; transition: .18s; }
.buy-btn:hover { filter: brightness(1.1); transform: translateY(-1px); }
.buy-btn.equip { background: rgba(111,242,208,.16); color: var(--teal); border: 1px solid rgba(111,242,208,.4); }
.buy-btn.equipped { background: rgba(255,255,255,.06); color: var(--muted); border: 1px solid var(--line); cursor: default; }
.buy-btn.cant { background: rgba(255,255,255,.06); color: #6f7890; border: 1px solid var(--line); }
.shop-foot { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-top: 18px; padding-top: 16px; border-top: 1px solid rgba(255,255,255,.08); font-size: 10px; color: var(--muted); }

.pause-panel { width: min(560px, 94vw); text-align: center; }
.pause-panel .panel-kicker { color: var(--pink); }
.pause-actions { display: flex; flex-direction: column; gap: 9px; margin: 20px auto 22px; width: min(320px, 100%); }
.pause-actions .play-btn { justify-content: center; }
.pause-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 18px; text-align: left; border-top: 1px solid rgba(255,255,255,.1); padding-top: 18px; }
.pause-controls div { display: flex; justify-content: space-between; gap: 8px; font-size: 10px; color: var(--muted); }
.pause-controls b { color: var(--teal); letter-spacing: .5px; white-space: nowrap; }
.pause-tip { margin: 18px 0 0; font-size: 10.5px; line-height: 1.6; color: #ffcf9a; background: rgba(255,209,102,.06); border: 1px solid rgba(255,209,102,.2); padding: 10px 12px; border-radius: 9px; text-align: left; }

.loading { position: absolute; inset: 0; z-index: 50; display: grid; place-content: center; justify-items: center; gap: 14px; background: var(--bg); }
.loading span { width: 40px; height: 40px; border-radius: 50%; border: 2px solid rgba(111,242,208,.2); border-top-color: var(--teal); animation: spin 0.9s linear infinite; }
.loading p { font-size: 9px; letter-spacing: 3px; color: var(--muted); }
@keyframes spin { to { transform: rotate(360deg); } }

/* ============================ RESPONSIVE ============================ */
@media (max-width: 1024px) {
  .quests { width: 236px; }
  .title-content { width: min(540px, 60vw); }
  .trick-buttons { grid-template-columns: repeat(2, 96px); }
  .minimap-wrap { width: 140px; height: 140px; }
}

@media (max-width: 820px), (pointer: coarse) {
  #hud { padding: calc(10px + var(--safe-t)) calc(12px + var(--safe-r)) calc(10px + var(--safe-b)) calc(12px + var(--safe-l)); }
  .brand-mark { width: 38px; height: 38px; font-size: 21px; border-radius: 9px; }
  .brand-text strong { font-size: 16px; }
  .brand-text span { font-size: 7px; letter-spacing: 2px; }
  .stat-pills { gap: 6px; }
  .pill { min-width: 86px; padding: 6px 10px; }
  .pill-value { font-size: 16px; }
  .hud-buttons .icon-btn { height: 32px; padding: 0 9px; font-size: 10px; }
  .minimap-wrap { width: 104px; height: 104px; padding: 5px; }
  .minimap-label { font-size: 6px; padding: 2px 6px; letter-spacing: 1.6px; }
  .quests { position: absolute; top: calc(78px + var(--safe-t)); left: calc(12px + var(--safe-l)); right: calc(12px + var(--safe-r)); width: auto; }
  .quests-head { padding-bottom: 5px; font-size: 8px; }
  #questList { flex-direction: row; gap: 6px; overflow-x: auto; padding-bottom: 3px; scrollbar-width: none; }
  #questList::-webkit-scrollbar { display: none; }
  .quest-card { min-width: 205px; padding: 7px 9px; gap: 7px; }
  .quest-icon { width: 25px; height: 25px; font-size: 12px; }
  .quest-title { font-size: 10px; }
  .quest-desc { font-size: 8.5px; }
  .quest-reward { font-size: 8.5px; }
  .quest-reroll { opacity: 1; }
  .controls-hint { display: none; }
  .speedo { width: 108px; height: 108px; left: calc(16px + var(--safe-l)); bottom: calc(164px + var(--safe-b)); }
  .speedo-center strong { font-size: 27px; }
  .speedo-center span { font-size: 6px; letter-spacing: 2px; }
  .speedo-scooter { font-size: 6px; letter-spacing: 1.2px; padding: 2px 6px; }
  .trick-buttons { grid-template-columns: repeat(2, 70px); gap: 5px; right: calc(12px + var(--safe-r)); bottom: calc(12px + var(--safe-b)); }
  .trick-btn { height: 40px; padding: 0 6px; gap: 4px; }
  .trick-btn .tb-key { width: 18px; height: 18px; font-size: 9px; }
  .trick-btn .tb-name { font-size: 7px; letter-spacing: .4px; }
  .touch-controls { display: block; }
  .joystick { width: 116px; height: 116px; bottom: calc(14px + var(--safe-b)); }
  .joystick-knob { width: 46px; height: 46px; }
  .touch-actions { bottom: calc(126px + var(--safe-b)); right: calc(14px + var(--safe-r)); }
  .touch-btn { width: 62px; height: 62px; font-size: 8px; }
  .wheelie-btn { width: 52px; height: 52px; font-size: 7px; }
  .move-meters { bottom: calc(196px + var(--safe-b)); width: min(280px, 62vw); }
  .toasts { bottom: calc(286px + var(--safe-b)); }
  .combo-box { top: calc(160px + var(--safe-t)); padding: 6px 12px; }
  .combo-box strong { font-size: 17px; }
  .location-banner { top: calc(40% + var(--safe-t)); }
  .trick-pop { top: 34%; }
  .title-screen { align-items: flex-end; }
  .title-content { width: 100%; margin: 0; padding: 20px 22px calc(24px + var(--safe-b)); }
  .title-logo .volt, .title-logo .city { font-size: clamp(58px, 17vw, 92px); }
  .title-copy, .title-controls, .title-corner, .title-scroll { display: none; }
  .title-stats { margin-top: 18px; gap: 20px; }
  .title-actions { margin-top: 18px; }
  .play-btn { padding: 13px 30px; font-size: 17px; }
  .shop-grid { grid-template-columns: 1fr 1fr; }
  .shop-panel { max-height: 94vh; }
  .panel-head { gap: 10px; }
  .shop-wallet { margin-left: auto; }
  .pause-controls { grid-template-columns: 1fr; }
}

@media (max-width: 560px) {
  .brand-text { display: none; }
  .stat-pills .score-pill { display: none; }
  .hud-buttons .shop-icon { padding: 0 8px; }
  .minimap-wrap { width: 86px; height: 86px; }
  .quests { top: calc(72px + var(--safe-t)); }
  .quest-card { min-width: 185px; }
  .shop-grid { grid-template-columns: 1fr; }
  .title-stats div:nth-child(3) { display: none; }
  .title-copy { display: none; }
  .title-actions { flex-wrap: wrap; }
  .move-meters { bottom: calc(210px + var(--safe-b)); }
  .bail-box strong { font-size: 32px; }
}

@media (max-height: 520px) and (orientation: landscape) {
  .quests { display: none; }
  .title-controls, .title-stats { display: none; }
  .title-logo .volt, .title-logo .city { font-size: 58px; }
  .move-meters { bottom: calc(14px + var(--safe-b)); width: 230px; }
  .speedo { width: 90px; height: 90px; bottom: calc(10px + var(--safe-b)); left: calc(150px + var(--safe-l)); }
  .trick-buttons { bottom: calc(10px + var(--safe-b)); }
  .joystick { width: 104px; height: 104px; bottom: calc(10px + var(--safe-b)); }
  .touch-actions { bottom: calc(10px + var(--safe-b)); right: calc(160px + var(--safe-r)); flex-direction: row; }
  .toasts { bottom: calc(120px + var(--safe-b)); }
  .minimap-wrap { display: none; }
}

import { SCOOTERS, WHEELIE, TRICK_LIST, TRICKS, CONTROLS } from './data.js';
import { formatMoney, speedKmh, landingCheck, trickName } from './logic.js';
import { PARK, ROAD_X, ROAD_Z } from './world.js';

const ICONS = {
  coin: '◉',
  trick: '⟳',
  wheelie: '↗',
  distance: '➜',
  air: '☁',
  combo: '✹',
  speed: '≫',
  visit: '⌂',
};

function el(id) { return document.getElementById(id); }

function scooterSvg(s) {
  return `
  <svg viewBox="0 0 220 110" aria-hidden="true">
    <defs>
      <linearGradient id="g-${s.id}" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stop-color="${s.color}"/>
        <stop offset="1" stop-color="${s.accent}"/>
      </linearGradient>
    </defs>
    <ellipse cx="110" cy="96" rx="78" ry="8" fill="${s.color}" opacity=".18"/>
    <circle cx="52" cy="82" r="16" fill="#13151d" stroke="#2d3242" stroke-width="3"/>
    <circle cx="170" cy="82" r="16" fill="#13151d" stroke="#2d3242" stroke-width="3"/>
    <circle cx="52" cy="82" r="5" fill="${s.color}"/>
    <circle cx="170" cy="82" r="5" fill="${s.color}"/>
    <path d="M52 82 L86 52 L150 52 L170 82" fill="none" stroke="${s.accent}" stroke-width="4" opacity=".5"/>
    <rect x="84" y="50" width="70" height="9" rx="4" fill="${s.deck}" stroke="${s.color}" stroke-width="2"/>
    <path d="M152 74 L168 79" stroke="${s.accent}" stroke-width="4" stroke-linecap="round"/>
    <path d="M150 50 L160 20" stroke="${s.accent}" stroke-width="5" stroke-linecap="round"/>
    <path d="M143 20 L177 20" stroke="${s.color}" stroke-width="5" stroke-linecap="round"/>
    <path d="M150 30 L168 30" stroke="${s.deck}" stroke-width="4" opacity=".6"/>
    <ellipse cx="110" cy="88" rx="54" ry="6" fill="${s.color}" opacity=".22"/>
    <circle cx="126" cy="44" r="4" fill="${s.color}"/>
  </svg>`;
}

export function createHud(handlers, input, audio) {
  const hud = el('hud');
  const title = el('title');
  const shop = el('shop');
  const pause = el('pause');

  const moneyValue = el('moneyValue');
  const scoreValue = el('scoreValue');
  const shopMoney = el('shopMoney');
  const speedValue = el('speedValue');
  const speedoArc = el('speedoArc');
  const scooterName = el('scooterName');
  const questList = el('questList');
  const locationBanner = el('locationBanner');
  const locName = el('locName');
  const comboBox = el('comboBox');
  const comboMult = el('comboMult');
  const comboPoints = el('comboPoints');
  const trickPop = el('trickPop');
  const trickNameEl = el('trickName');
  const trickPointsEl = el('trickPoints');
  const toasts = el('toasts');
  const wheelieMeter = el('wheelieMeter');
  const wheelieMarker = el('wheelieMarker');
  const wheelieHint = el('wheelieHint');
  const rotDial = el('rotDial');
  const rotNeedle = el('rotNeedle');
  const rotTrick = el('rotTrick');
  const rotDegrees = el('rotDegrees');
  const bailBox = el('bailBox');
  const bailReason = el('bailReason');
  const touchControls = el('touchControls');
  const joystick = el('joystick');
  const joystickKnob = el('joystickKnob');
  const trickButtons = el('trickButtons');
  const speedlines = el('speedlines');
  const titleBest = el('titleBest');
  const titleOwned = el('titleOwned');
  const muteBtn = el('muteBtn');
  const pauseMuteBtn = el('pauseMuteBtn');

  let currentQuests = [];
  let questCards = new Map();
  let lastBailTimer = 0;
  let lastLocTimer = 0;
  let trickTimer = 0;
  let titleShopOpen = false;

  /* ---------------- speedo ticks ---------------- */
  const ticks = el('speedoTicks');
  if (ticks) {
    const NS = 'http://www.w3.org/2000/svg';
    for (let i = 0; i <= 24; i++) {
      const a = (i / 24) * 270 - 135;
      const major = i % 6 === 0;
      const line = document.createElementNS(NS, 'line');
      const rad = (a - 90) * Math.PI / 180;
      const r1 = 61;
      const r2 = major ? 52 : 56;
      line.setAttribute('x1', 80 + Math.cos(rad) * r1);
      line.setAttribute('y1', 80 + Math.sin(rad) * r1);
      line.setAttribute('x2', 80 + Math.cos(rad) * r2);
      line.setAttribute('y2', 80 + Math.sin(rad) * r2);
      line.setAttribute('stroke', major ? 'rgba(255,255,255,.45)' : 'rgba(255,255,255,.16)');
      line.setAttribute('stroke-width', major ? 2 : 1);
      ticks.appendChild(line);
    }
  }
  const arcLen = 2 * Math.PI * 70;

  /* ---------------- minimap ---------------- */
  const minimap = el('minimap');
  const mctx = minimap.getContext('2d');
  const mapScale = (minimap.width - 18) / 380;
  const off = document.createElement('canvas');
  off.width = off.height = minimap.width;
  const octx = off.getContext('2d');
  const WC = minimap.width / 2;
  function wx(x) { return WC + x * mapScale; }
  function wz(z) { return WC + z * mapScale; }

  function drawStaticMap() {
    const w = off.width;
    octx.clearRect(0, 0, w, w);
    octx.fillStyle = '#0d1220';
    octx.fillRect(0, 0, w, w);
    // blocks
    octx.fillStyle = 'rgba(60,70,95,.28)';
    for (const bx of [-134, -78, 78, 134]) for (const bz of [-130, -74, 74, 130]) {
      octx.fillRect(wx(bx - 22), wz(bz - 22), 44 * mapScale, 44 * mapScale);
    }
    // roads
    octx.strokeStyle = 'rgba(170,185,215,.35)';
    octx.lineWidth = 12 * mapScale;
    for (const x of ROAD_X) {
      octx.beginPath(); octx.moveTo(wx(x), 0); octx.lineTo(wx(x), w); octx.stroke();
    }
    for (const z of ROAD_Z) {
      octx.beginPath(); octx.moveTo(0, wz(z)); octx.lineTo(w, wz(z)); octx.stroke();
    }
    // park
    octx.fillStyle = 'rgba(111,242,208,.16)';
    octx.strokeStyle = 'rgba(111,242,208,.7)';
    octx.lineWidth = 1.5;
    const pw = (PARK.maxX - PARK.minX) * mapScale;
    const ph = (PARK.maxZ - PARK.minZ) * mapScale;
    octx.fillRect(wx(PARK.minX), wz(PARK.minZ), pw, ph);
    octx.strokeRect(wx(PARK.minX), wz(PARK.minZ), pw, ph);
    // ramps
    octx.fillStyle = 'rgba(255,209,102,.6)';
    for (const [x, z, r] of [[0, -28, 4], [0, -12, 4], [0, 9, 3], [-24, 10, 3], [-38, 10, 3], [38, 10, 3], [25, 28, 2]]) {
      octx.beginPath();
      octx.arc(wx(x), wz(z), r, 0, Math.PI * 2);
      octx.fill();
    }
    // N marker
    octx.fillStyle = 'rgba(255,255,255,.4)';
    octx.font = '700 9px sans-serif';
    octx.textAlign = 'center';
    octx.fillText('N', WC, 12);
  }
  drawStaticMap();

  let mapAccum = 0;

  function drawMinimap(state) {
    if (!state) return;
    mctx.clearRect(0, 0, minimap.width, minimap.height);
    mctx.drawImage(off, 0, 0);
    // coins
    if (state.coins) {
      mctx.fillStyle = 'rgba(255,209,102,.95)';
      for (const c of state.coins) {
        if (!c.active) continue;
        mctx.fillRect(wx(c.x) - 1, wz(c.z) - 1, 2, 2);
      }
    }
    // player
    const px = wx(state.x);
    const pz = wz(state.z);
    mctx.save();
    mctx.translate(px, pz);
    mctx.rotate(-state.yaw);
    mctx.beginPath();
    mctx.moveTo(0, -7);
    mctx.lineTo(5, 5);
    mctx.lineTo(0, 2);
    mctx.lineTo(-5, 5);
    mctx.closePath();
    mctx.fillStyle = '#6ff2d0';
    mctx.shadowColor = '#6ff2d0';
    mctx.shadowBlur = 8;
    mctx.fill();
    mctx.restore();
    // view cone
    mctx.beginPath();
    mctx.moveTo(px, pz);
    mctx.arc(px, pz, 17, -state.yaw - Math.PI / 2 - 0.5, -state.yaw - Math.PI / 2 + 0.5);
    mctx.closePath();
    mctx.fillStyle = 'rgba(111,242,208,.12)';
    mctx.fill();
  }

  /* ---------------- quests ---------------- */
  function questCard(q, index) {
    const card = document.createElement('div');
    card.className = 'quest-card';
    card.innerHTML = `
      <div class="quest-icon">${ICONS[q.icon] || '✦'}</div>
      <div class="quest-body">
        <div class="quest-title"></div>
        <div class="quest-desc"></div>
        <div class="quest-reward"></div>
        <div class="quest-progress"><i></i></div>
      </div>
      <button class="quest-reroll" title="Reroll quest" aria-label="Reroll quest">↻</button>
    `;
    card.querySelector('.quest-reroll').addEventListener('click', (e) => {
      e.stopPropagation();
      audio.ui();
      handlers.reroll(index);
    });
    questList.appendChild(card);
    return card;
  }

  function paintQuest(card, q) {
    card.querySelector('.quest-title').textContent = q.title;
    card.querySelector('.quest-desc').textContent = q.desc;
    card.querySelector('.quest-reward').textContent = `REWARD ${formatMoney(q.reward)}`;
    const pct = Math.max(0, Math.min(1, q.progress / q.target)) * 100;
    card.querySelector('.quest-progress i').style.width = pct + '%';
    card.classList.toggle('done', !!q.done);
  }

  function updateQuests(quests) {
    currentQuests = quests;
    const ids = quests.map((q) => q.id).join(',');
    const oldIds = [...questCards.keys()].join(',');
    if (ids !== oldIds) {
      questList.innerHTML = '';
      questCards = new Map();
      quests.forEach((q, i) => {
        const card = questCard(q, i);
        questCards.set(q.id, card);
        paintQuest(card, q);
      });
    } else {
      quests.forEach((q) => {
        const card = questCards.get(q.id);
        if (card) paintQuest(card, q);
      });
    }
  }

  function updateQuestProgress(quests) {
    quests.forEach((q) => {
      const card = questCards.get(q.id);
      if (card) paintQuest(card, q);
    });
    currentQuests = quests;
  }

  /* ---------------- shop ---------------- */
  function statRow(label, value, max, display) {
    const pct = Math.max(6, Math.min(100, (value / max) * 100));
    return `<div class="sc-stat"><span>${label}</span><div class="sc-bar"><i style="width:${pct}%"></i></div><b>${display}</b></div>`;
  }

  function renderShop(save) {
    const grid = el('shopGrid');
    if (!grid) return;
    grid.innerHTML = '';
    const equipped = SCOOTERS.find((s) => s.id === save.equipped) || SCOOTERS[0];
    el('shopMoney').textContent = formatMoney(save.money);
    SCOOTERS.forEach((s) => {
      const owned = save.owned.includes(s.id);
      const isEquipped = save.equipped === s.id;
      const canBuy = save.money >= s.price;
      const card = document.createElement('article');
      card.className = `shop-card ${owned ? 'owned' : 'locked'} ${isEquipped ? 'equipped' : ''}`;
      card.innerHTML = `
        <div class="sc-top">
          <div>
            <div class="sc-name">${s.name}</div>
            <div class="sc-tag">${s.tagline}</div>
          </div>
          <span class="sc-badge ${isEquipped ? 'equipped' : owned ? 'owned' : ''}">${isEquipped ? 'RIDING' : owned ? 'OWNED' : s.price === 0 ? 'FREE' : 'FOR SALE'}</span>
        </div>
        <div class="sc-art">${scooterSvg(s)}</div>
        <div class="sc-stats">
          ${statRow('TOP', s.top, 43, speedKmh(s.top) + ' km/h')}
          ${statRow('ACCEL', s.accel, 17, s.accel.toFixed(1))}
          ${statRow('GRIP', s.handling, 1.26, (s.handling * 100).toFixed(0) + '%')}
          ${statRow('SPIN', s.spin, 1.22, s.spin.toFixed(2) + 'x')}
        </div>
        <div class="sc-foot">
          <span class="sc-price ${owned ? 'owned' : ''}">${owned ? 'OWNED' : formatMoney(s.price)}</span>
          <button class="buy-btn ${isEquipped ? 'equipped' : owned ? 'equip' : canBuy ? '' : 'cant'}">${isEquipped ? 'EQUIPPED' : owned ? 'EQUIP' : canBuy ? 'BUY' : 'NEED ' + formatMoney(s.price - save.money)}</button>
        </div>
      `;
      const btn = card.querySelector('.buy-btn');
      if (isEquipped) {
        btn.disabled = true;
      } else if (owned) {
        btn.addEventListener('click', () => { audio.ui(); handlers.equip(s.id); });
      } else if (canBuy) {
        btn.addEventListener('click', () => { handlers.buy(s.id); });
      } else {
        btn.disabled = true;
      }
      grid.appendChild(card);
    });
    return equipped;
  }

  /* ---------------- public API ---------------- */
  function setMoney(v) {
    moneyValue.textContent = formatMoney(v);
    shopMoney.textContent = formatMoney(v);
  }
  function setScore(v) {
    scoreValue.textContent = formatMoney(v);
  }
  function setSpeed(ms, max) {
    const kmh = speedKmh(ms);
    speedValue.textContent = kmh;
    const pct = Math.max(0, Math.min(1, ms / Math.max(1, max * 1.15)));
    speedoArc.style.strokeDasharray = arcLen;
    speedoArc.style.strokeDashoffset = arcLen * (1 - pct);
    speedoArc.style.stroke = pct > 0.82 ? '#ffd166' : pct > 0.55 ? '#6ff2d0' : '#6ff2d0';
    speedlines.classList.toggle('fast', pct > 0.7);
  }
  function setScooter(s) {
    scooterName.textContent = s.name.toUpperCase();
  }
  function showTrick(text, points, color) {
    trickNameEl.textContent = text;
    trickPointsEl.textContent = points > 0 ? `+${Math.round(points)}` : 'BAILED';
    trickPop.style.setProperty('--trick-color', color || '#ffd166');
    trickPop.classList.remove('hidden');
    trickPop.style.animation = 'none';
    void trickPop.offsetWidth;
    trickPop.style.animation = '';
    clearTimeout(trickTimer);
    trickTimer = setTimeout(() => trickPop.classList.add('hidden'), 1700);
  }
  function showToast(text, kind = '') {
    const t = document.createElement('div');
    t.className = `toast ${kind}`;
    t.textContent = text;
    toasts.appendChild(t);
    while (toasts.children.length > 4) toasts.removeChild(toasts.firstChild);
    setTimeout(() => t.remove(), 3500);
  }
  function setCombo(mult, points) {
    if (mult > 1 || points > 0) {
      comboBox.classList.remove('hidden');
      comboMult.textContent = `COMBO ×${Math.max(1, mult)}`;
      comboPoints.textContent = Math.round(points);
      comboBox.classList.toggle('hot', mult >= 3);
    } else {
      comboBox.classList.add('hidden');
    }
  }
  function setWheelie(angle, active, danger = false) {
    if (!active || angle <= 0.5) {
      wheelieMeter.classList.add('hidden');
      return;
    }
    wheelieMeter.classList.remove('hidden');
    const pct = Math.max(0, Math.min(100, (angle / WHEELIE.max) * 100));
    wheelieMarker.style.left = pct + '%';
    wheelieMeter.classList.toggle('danger', danger);
    wheelieHint.textContent = danger ? 'TOO FAR — BAIL!' : 'RELEASE IN THE GREEN';
  }
  function setRotation(angle, trick, show) {
    if (!show || !trick) {
      rotDial.classList.add('hidden');
      return;
    }
    rotDial.classList.remove('hidden');
    const t = TRICKS[trick];
    rotNeedle.style.transform = `rotate(${angle}deg)`;
    rotTrick.textContent = t ? t.name.toUpperCase() : trick.toUpperCase();
    const deg = Math.round(Math.abs(angle));
    const chk = landingCheck(angle);
    rotDegrees.textContent = `${deg}° ${chk.clean ? '✓' : ''}`;
    rotDegrees.style.color = chk.clean ? '#6ff2d0' : '#ff9389';
  }
  function setAirborne(on) {
    trickButtons.querySelectorAll('.trick-btn').forEach((b) => b.classList.toggle('armed', on));
  }
  function bail(reason) {
    bailReason.textContent = reason;
    bailBox.classList.remove('hidden');
    bailBox.style.animation = 'none';
    void bailBox.offsetWidth;
    bailBox.style.animation = '';
    clearTimeout(lastBailTimer);
    lastBailTimer = setTimeout(() => bailBox.classList.add('hidden'), 1800);
  }
  function location(name) {
    locName.textContent = name.toUpperCase();
    locationBanner.classList.remove('hidden');
    locationBanner.style.animation = 'none';
    void locationBanner.offsetWidth;
    locationBanner.style.animation = '';
    clearTimeout(lastLocTimer);
    lastLocTimer = setTimeout(() => locationBanner.classList.add('hidden'), 4400);
  }
  function updateMinimapState(state) {
    mapAccum += state.dt || 0;
    if (mapAccum > 0.08) {
      mapAccum = 0;
      drawMinimap(state);
    }
  }
  function showTitle(on) {
    title.classList.toggle('hidden', !on);
  }
  function showHud(on) {
    hud.classList.toggle('hidden', !on);
  }
  function setMuted(m) {
    muteBtn.textContent = m ? '✕' : '♪';
    muteBtn.setAttribute('aria-label', m ? 'Unmute sound' : 'Mute sound');
    if (pauseMuteBtn) pauseMuteBtn.textContent = m ? 'SOUND: OFF' : 'SOUND: ON';
  }
  function updateTitleStats(save) {
    titleBest.textContent = formatMoney(save.bestScore);
    titleOwned.textContent = `${save.owned.length} / ${SCOOTERS.length}`;
  }
  function setPaused(on) { pause.classList.toggle('hidden', !on); }
  function setShopOpen(on) { shop.classList.toggle('hidden', !on); }
  function shopVisible() { return !shop.classList.contains('hidden'); }
  function pauseVisible() { return !pause.classList.contains('hidden'); }

  /* ---------------- wiring ---------------- */
  el('playBtn').addEventListener('click', () => { audio.init(); audio.ui(); handlers.play(); });
  el('titleShopBtn').addEventListener('click', () => { audio.init(); audio.ui(); handlers.openShop(true); });
  el('shopClose').addEventListener('click', () => { audio.ui(); handlers.closeShop(); });
  el('shopResume').addEventListener('click', () => { audio.ui(); handlers.closeShop(); });
  el('resumeBtn').addEventListener('click', () => { audio.ui(); handlers.resume(); });
  el('pauseShopBtn').addEventListener('click', () => { audio.ui(); handlers.openShop(false); });
  el('restartBtn').addEventListener('click', () => { audio.ui(); handlers.restart(); });
  el('pauseMuteBtn').addEventListener('click', () => { handlers.mute(); });
  muteBtn.addEventListener('click', () => { handlers.mute(); });
  el('shopBtn').addEventListener('click', () => { audio.ui(); handlers.openShop(false); });
  el('pauseBtn').addEventListener('click', () => { audio.ui(); handlers.pause(); });
  el('rerollAll').addEventListener('click', () => { audio.ui(); handlers.rerollAll(); });

  // trick buttons: usable with mouse and touch
  trickButtons.querySelectorAll('.trick-btn').forEach((btn) => {
    const id = btn.dataset.trick;
    const press = (e) => {
      e.preventDefault();
      input.setTouchTrick(id);
      btn.classList.add('pressed');
    };
    const release = () => {
      if (input.state.trick === id) input.setTouchTrick(null);
      btn.classList.remove('pressed');
    };
    btn.addEventListener('pointerdown', press);
    btn.addEventListener('pointerup', release);
    btn.addEventListener('pointerleave', release);
    btn.addEventListener('pointercancel', release);
  });

  // joystick
  let joyId = null;
  function joyMove(e) {
    const rect = joystick.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    let dx = e.clientX - cx;
    let dy = e.clientY - cy;
    const max = rect.width * 0.36;
    const len = Math.hypot(dx, dy);
    if (len > max) { dx = (dx / len) * max; dy = (dy / len) * max; }
    joystickKnob.style.transform = `translate(${dx}px, ${dy}px)`;
    input.setTouchMove(Math.max(-1, Math.min(1, -dy / max)), Math.max(-1, Math.min(1, dx / max)));
  }
  joystick.addEventListener('pointerdown', (e) => {
    joystick.setPointerCapture(e.pointerId);
    joyId = e.pointerId;
    joyMove(e);
  });
  joystick.addEventListener('pointermove', (e) => {
    if (joyId === e.pointerId) joyMove(e);
  });
  function joyEnd(e) {
    if (joyId !== null && e.pointerId !== joyId) return;
    joyId = null;
    joystickKnob.style.transform = 'translate(0, 0)';
    input.setTouchMove(0, 0);
  }
  joystick.addEventListener('pointerup', joyEnd);
  joystick.addEventListener('pointercancel', joyEnd);
  joystick.addEventListener('pointerleave', (e) => { if (joyId === e.pointerId) joyEnd(e); });

  const wheelieBtn = el('touchWheelie');
  const wheelieOn = (e) => { e.preventDefault(); input.setTouchWheelie(true); wheelieBtn.style.transform = 'scale(.94)'; };
  const wheelieOff = () => { input.setTouchWheelie(false); wheelieBtn.style.transform = ''; };
  wheelieBtn.addEventListener('pointerdown', wheelieOn);
  wheelieBtn.addEventListener('pointerup', wheelieOff);
  wheelieBtn.addEventListener('pointercancel', wheelieOff);
  wheelieBtn.addEventListener('pointerleave', wheelieOff);
  const jumpBtn = el('touchJump');
  jumpBtn.addEventListener('pointerdown', (e) => { e.preventDefault(); input.tapJump(); jumpBtn.style.transform = 'scale(.94)'; });
  jumpBtn.addEventListener('pointerup', () => { jumpBtn.style.transform = ''; });
  jumpBtn.addEventListener('pointercancel', () => { jumpBtn.style.transform = ''; });

  // Controls hint can be dismissed with a tap on touch devices.
  el('controlsHint').addEventListener('click', (e) => e.currentTarget.remove());

  return {
    showTitle, showHud, setMoney, setScore, setSpeed, setScooter,
    updateQuests, updateQuestProgress, renderShop, showTrick, showToast,
    setCombo, setWheelie, setRotation, setAirborne, bail, location,
    updateMinimapState, setMuted, updateTitleStats, setPaused, setShopOpen,
    shopVisible, pauseVisible, audioReady: () => audio.init(),
    setTitleShopOpen: (v) => { titleShopOpen = v; },
  };
}

